from ute_ue.ltebearer import LteBearer


class RtgBearer(LteBearer):
    """Rtg Bearer implementation"""

    def __init__(self, identifiers):
        """
        Definition of Abstract Bearer API
        :param identifiers: BearerIdentification init parameters
        used LTE standard params: bearer_id, qci, pdn
        library specific: ue_id, type eg.: 'wts'

        More info in about LTE standard elements in:
        TS 36.413 available at http://www.etsi.org/deliver/etsi_ts/136400_136499/136413/12.03.00_60/ts_136413v120300p.pdf

        (erab_id (9.2.1.2),
        erab_level_qos (9.2.1.15):
            [qci,
            alloc_and_reten_prio (9.2.1.60):
                [prio_lvl, preempt_capability, preempt_vulnerability],
            gbr_qos_information (9.2.1.18 only for GBR!): [max_bit_rate_dl, max_bit_rate_ul, guaranteed_bit_rate_dl, guaranteed_bit_rate_ul]]
        transport_layer_address (9.2.2.1),
        gtp_teid (9.2.2.2))
        """
        super(RtgBearer, self).__init__(identifiers)

    def __eq__(self, other):
        if other is None:
            return False
        return self.bearer_identification == other.bearer_identification

    def is_active(self):
        """
        Check if bearer is currently active.

        :return: True if bearer is currently active; else False
        """
        raise NotImplementedError
        # return False

    def get_bearer_id(self):
        """
        Return bearer id

        :return: bearer_id
        """
        return self.bearer_identification['rtg']['bearer_id']
